     1	/**
     2	 * The result envelope every Server Action and Route Handler returns. Actions
     3	 * never throw for expected failures — they return `ActionResult` so the client
     4	 * form layer can render field errors without an error boundary.
     5	 */
     6	
     7	export type ErrorCode =
     8	  | "unauthorized"
     9	  | "forbidden"
    10	  | "not_found"
    11	  | "validation_failed"
    12	  | "conflict"
    13	  | "rate_limited"
    14	  | "plan_limit_exceeded"
    15	  | "tenant_scope_violation"
    16	  | "internal_error";
    17	
    18	export interface AppErrorShape {
    19	  readonly code: ErrorCode;
    20	  readonly message: string;
    21	  /** Zod-style field path → messages, for react-hook-form to consume. */
    22	  readonly fieldErrors?: Readonly<Record<string, readonly string[]>>;
    23	  readonly meta?: Readonly<Record<string, string | number | boolean>>;
    24	}
    25	
    26	export type Result<T, E = AppErrorShape> =
    27	  | { readonly ok: true; readonly data: T }
    28	  | { readonly ok: false; readonly error: E };
    29	
    30	/** What a Server Action returns to a `useActionState` reducer. */
    31	export type ActionResult<T> = Result<T> & {
    32	  /** Monotonic token so the client can distinguish two identical results. */
    33	  readonly submittedAt?: string;
    34	};
    35	
    36	export interface ApiErrorBody {
    37	  readonly error: AppErrorShape;
    38	}
    39	
    40	export function ok<T>(data: T): Result<T> {
    41	  return { ok: true, data };
    42	}
    43	
    44	export function err<T = never>(error: AppErrorShape): Result<T> {
    45	  return { ok: false, error };
    46	}
    47	
    48	export function isOk<T, E>(
    49	  result: Result<T, E>,
    50	): result is { ok: true; data: T } {
    51	  return result.ok;
    52	}

