     1	"use server";
     2	
     3	/**
     4	 * Signs a user in and sets the session cookie.
     5	 *
     6	 * Owner D. Runs before any tenant is known, so it cannot go through
     7	 * `withAction()` — there is no `Actor` to resolve yet. The rate limit is
     8	 * charged against the anonymous bucket to blunt credential stuffing.
     9	 *
    10	 * Must call (do not reimplement): loginSchema, setSessionCookie,
    11	 * consumeRateLimit
    12	 */
    13	
    14	import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
    15	import { RateLimitedError } from "@/actions/_lib/action-errors";
    16	import { toActionResult } from "@/lib/errors";
    17	import { consumeRateLimit } from "@/lib/rate-limit";
    18	import { setSessionCookie } from "@/lib/session";
    19	import { loginSchema } from "@/schemas/auth";
    20	import { login } from "@/server/services/auth-service";
    21	import { resolveSession } from "@/server/services/session-service";
    22	import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
    23	import type { ActionResult } from "@/types/api";
    24	import type { SessionPrincipal } from "@/types/member";
    25	
    26	const LOGIN_BUCKET = "auth:login";
    27	
    28	export async function loginAction(raw: unknown): Promise<ActionResult<SessionPrincipal>> {
    29	  const parsed = loginSchema.safeParse(raw);
    30	  if (!parsed.success) {
    31	    return toActionResult(parsed.error);
    32	  }
    33	
    34	  try {
    35	    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, LOGIN_BUCKET);
    36	    if (!verdict.allowed) {
    37	      throw new RateLimitedError(LOGIN_BUCKET, verdict.resetAt);
    38	    }
    39	
    40	    const { token } = await login(parsed.data);
    41	    const principal = await resolveSession(token);
    42	    if (principal === null) {
    43	      throw new UnauthorizedActionError("That sign-in could not be completed.");
    44	    }
    45	
    46	    await setSessionCookie(token, principal.expiresAt);
    47	    return { ok: true, data: principal, submittedAt: new Date().toISOString() };
    48	  } catch (error) {
    49	    return toActionResult(error);
    50	  }
    51	}
