import { RateLimitedError, consumeRateLimit } from "@/lib/rate-limit";
import { DuplicateAccountError } from "@/lib/errors";
import { SLUG_MAX_LENGTH, SLUG_MIN_LENGTH, slugify, uniqueSlug } from "@/lib/slug";
import { ORGANIZATION_NAME_MAX_LENGTH } from "@/schemas/organization";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { toIsoTimestamp } from "@/types/common";
import { createOrganization } from "./organization-service";
import { renderEmail, sendEmail } from "./email-service";
import { createSessionToken } from "./session-service";
import type {
  LoginInput,
  PasswordResetConfirmInput,
  PasswordResetRequestInput,
  RegisterInput,
} from "@/schemas/auth";
import type { OrgId, SessionId } from "@/types/common";
import type { User } from "@/types/member";
import type { Organization } from "@/types/organization";

/** Buckets guarding the unauthenticated endpoints. */
const REGISTER_BUCKET = "auth:register";
const LOGIN_BUCKET = "auth:login";
const RESET_BUCKET = "auth:password-reset";

/**
 * Rate limiting before a session exists has no tenant to charge against, so
 * every unauthenticated attempt is billed to this sentinel bucket.
 */
const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/** How long a password-reset link stays usable. */
const RESET_TTL_MS = 60 * 60 * 1000;

/** Suffix of the first workspace's name; the display name is shortened to fit around it. */
const WORKSPACE_NAME_SUFFIX = "'s workspace";

/** Slug used when the display name leaves nothing usable (ADR 0003 §2). */
const FALLBACK_WORKSPACE_SLUG = "workspace";

/**
 * Registration creates the user and their first workspace in one step — a
 * Taskflow account with no organization cannot do anything, so there is no
 * intermediate state where one exists without the other.
 *
 * Refusals happen before anything is written: the rate limit is charged once
 * per attempt, and an address that already has an account is a `conflict`.
 * Deriving the workspace name and slug never refuses a sign-up (ADR 0003 §1–2).
 */
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, REGISTER_BUCKET);
  if (!verdict.allowed) {
    throw new RateLimitedError(REGISTER_BUCKET, verdict.resetAt);
  }

  const passwordHash = await hashPassword(input.password);

  if (await userRepo.findUserByEmail(input.email)) {
    throw new DuplicateAccountError();
  }

  const slug = await firstWorkspaceSlug(input.name);

  const user = await userRepo.insertUser({
    email: input.email,
    name: input.name,
    passwordHash,
  });

  const org = await createOrganization(user.id, {
    name: firstWorkspaceName(input.name),
    slug,
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

/**
 * `<display name>'s workspace`. When the whole would exceed the limit the
 * workspace schema enforces, the display name is shortened until it fits, so
 * the result still ends in the suffix. Trimming is by code point so a
 * surrogate pair is never split.
 */
function firstWorkspaceName(displayName: string): string {
  const room = ORGANIZATION_NAME_MAX_LENGTH - WORKSPACE_NAME_SUFFIX.length;
  let shortened = displayName;
  while (shortened.length > room) {
    shortened = Array.from(shortened).slice(0, -1).join("");
  }
  return `${shortened}${WORKSPACE_NAME_SUFFIX}`;
}

/**
 * The first workspace's slug is derived from the display name. A name whose
 * slug is shorter than the minimum (`J`, `山田`) falls back to `workspace`;
 * `uniqueSlug()` skips reserved words (`Admin` becomes `admin-2`) and suffixes
 * collisions. The result is always valid, so `createOrganization` accepts it.
 */
async function firstWorkspaceSlug(displayName: string): Promise<string> {
  const derived = slugify(displayName);
  const base =
    derived.length >= SLUG_MIN_LENGTH ? derived : FALLBACK_WORKSPACE_SLUG;
  const taken = await orgRepo.listTakenOrgSlugs(
    base.slice(0, SLUG_MAX_LENGTH - 5),
  );
  return uniqueSlug(base, taken);
}

/**
 * Credential login. The rate limit is charged before the password is checked,
 * so a brute-force run is throttled whether or not it guesses correctly, and
 * both failure modes return the same message.
 */
export async function login(
  input: LoginInput,
): Promise<{ user: User; token: string }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, LOGIN_BUCKET);
  if (!verdict.allowed) {
    throw new RateLimitedError(LOGIN_BUCKET, verdict.resetAt);
  }

