import { login, register } from "@/server/services/auth-service";
import { resetTestDb, setupTestDb } from "../helpers/db";

const PASSWORD = "Sample-Passw0rd!";

function input(name: string, email: string) {
  return {
    name,
    email,
    password: PASSWORD,
    confirmPassword: PASSWORD,
    acceptTerms: true as const,
  };
}

describe("scratch sign-up checks", () => {
  beforeAll(async () => {
    await setupTestDb();
  });
  beforeEach(async () => {
    await resetTestDb();
    resetRateLimits();
  });

  it.each([
    ["Admin", "admin-2", "Admin's workspace"],
    ["Billing", "billing-2", "Billing's workspace"],
    ["Taskflow", "taskflow-2", "Taskflow's workspace"],
    ["J", "workspace", "J's workspace"],
    ["Al", "al", "Al's workspace"],
    ["山田", "workspace", "山田's workspace"],
  ])("registers %s with slug %s", async (name, slug, orgName) => {
    const { org } = await register(input(name, `${slug}@example.com`));
    expect(org.slug).toBe(slug);
    expect(org.name).toBe(orgName);
  });

  it("shortens an 80-character name so the workspace name fits the settings limit", async () => {
    const name = "é".repeat(80);
    const { org, user } = await register(input(name, "long@example.com"));
    expect(org.name.length).toBeLessThanOrEqual(64);
    expect(org.name.endsWith("'s workspace")).toBe(true);
    const parsed = updateOrganizationSchema.safeParse({
      orgId: org.id,
